INSERT INTO JobRequisition (Title, RequisitionCode, RecruitmentRound, DepartmentId, HiringManagerId, NumberOfPositions, EmploymentType, MinSalary, MaxSalary, ReasonForHiring, JobDescription, RequirementDetails, RequiredGender, ProbationDuration, WorkModel, WorkLocation, ExpectedStartDate, ApprovalStatus, CreatedAt, UpdatedAt) VALUES (N'Senior Java Backend Engineer', N'REQ-2026-0001', 1, 1, 5, 2, N'Full-time', 30000000.00, 45000000.00, N'Mở rộng đội ngũ kỹ thuật phát triển hệ thống Core RMS & Microservices', N'Phát triển backend RESTful APIs bằng Spring Boot, tối ưu hóa cơ sở dữ liệu SQL Server, triển khai Docker/Kubernetes.', N'Tối thiểu 3 năm kinh nghiệm lập trình Java, thành thạo Spring Boot, JPA/Hibernate, hiểu sâu về Caching Redis và Message Queue RabbitMQ.', N'Any', N'2 tháng', N'Hybrid', N'Tầng 8, Tòa nhà RMS Tower, Phố Duy Tân, Cầu Giấy, Hà Nội', '2026-11-01', N'Approved', '2026-09-10 09:00:00', '2026-09-15 10:00:00');
INSERT INTO JobRequisition (Title, RequisitionCode, RecruitmentRound, DepartmentId, HiringManagerId, NumberOfPositions, EmploymentType, MinSalary, MaxSalary, ReasonForHiring, JobDescription, RequirementDetails, RequiredGender, ProbationDuration, WorkModel, WorkLocation, ExpectedStartDate, ApprovalStatus, CreatedAt, UpdatedAt) VALUES (N'Frontend ReactJS Developer', N'REQ-2026-0002', 1, 1, 5, 2, N'Full-time', 20000000.00, 32000000.00, N'Xây dựng giao diện web portal quản trị và cổng ứng viên hiện đại, responsive', N'Phát triển module giao diện người dùng bằng React 18, TypeScript, TailwindCSS/Vanilla CSS, tích hợp REST APIs.', N'Tối thiểu 2 năm kinh nghiệm ReactJS, thành thạo Redux Toolkit hoặc Zustand, có kinh nghiệm tối ưu hóa hiệu năng web và UI/UX.', N'Any', N'2 tháng', N'Hybrid', N'Tầng 8, Tòa nhà RMS Tower, Phố Duy Tân, Cầu Giấy, Hà Nội', '2026-11-01', N'Approved', '2026-09-11 10:00:00', '2026-09-16 11:00:00');
INSERT INTO JobRequisition (Title, RequisitionCode, RecruitmentRound, DepartmentId, HiringManagerId, NumberOfPositions, EmploymentType, MinSalary, MaxSalary, ReasonForHiring, JobDescription, RequirementDetails, RequiredGender, ProbationDuration, WorkModel, WorkLocation, ExpectedStartDate, ApprovalStatus, CreatedAt, UpdatedAt) VALUES (N'QA Automation Engineer', N'REQ-2026-0003', 1, 1, 5, 1, N'Full-time', 18000000.00, 28000000.00, N'Thiết lập quy trình kiểm thử tự động, đảm bảo chất lượng hệ thống phần mềm trước release', N'Xây dựng test automation framework cho API và Web UI bằng Playwright/Selenium và Java/Python, tích hợp CI/CD.', N'Tối thiểu 2 năm kinh nghiệm Automation Test, thành thạo Postman/Newman, k6 hoặc JMeter, hiểu biết về quy trình Agile/Scrum.', N'Any', N'2 tháng', N'On-site', N'Tầng 8, Tòa nhà RMS Tower, Phố Duy Tân, Cầu Giấy, Hà Nội', '2026-11-15', N'Approved', '2026-09-12 08:30:00', '2026-09-17 14:00:00');
INSERT INTO JobRequisition (Title, RequisitionCode, RecruitmentRound, DepartmentId, HiringManagerId, NumberOfPositions, EmploymentType, MinSalary, MaxSalary, ReasonForHiring, JobDescription, RequirementDetails, RequiredGender, ProbationDuration, WorkModel, WorkLocation, ExpectedStartDate, ApprovalStatus, CreatedAt, UpdatedAt) VALUES (N'Business Development Executive (B2B)', N'REQ-2026-0004', 1, 2, 6, 2, N'Full-time', 15000000.00, 25000000.00, N'Mở rộng thị trường khách hàng doanh nghiệp SME sử dụng giải pháp phần mềm', N'Tìm kiếm khách hàng tiềm năng B2B, tư vấn giải pháp chuyển đổi số, đàm phán và ký kết hợp đồng dịch vụ phần mềm.', N'Tối thiểu 1 năm kinh nghiệm Sales B2B khối phần mềm/IT, kỹ năng giao tiếp và thuyết trình xuất sắc, tiếng Anh giao tiếp tốt.', N'Any', N'2 tháng', N'On-site', N'Quận 1, TP. Hồ Chí Minh & Cầu Giấy, Hà Nội', '2026-11-15', N'Approved', '2026-09-15 14:00:00', '2026-09-18 09:30:00');
