INSERT INTO JobPosting (RequisitionId, PostingTitle, JobDescription, JobRequirements, Benefits, SalaryDisplay, WorkLocation, PostingDate, ApplicationDeadline, PostingStatus, CreatedBy, CreatedAt) VALUES (1, N'Senior Java Backend Engineer (Spring Boot / Microservices)', N'Chúng tôi tìm kiếm Senior Java Engineer tham gia xây dựng nền tảng quản trị tuyển dụng và nhân sự RMS hiệu năng cao.', N'- Tối thiểu 3 năm làm việc với Java, Spring Boot, Hibernate\n- Thành thạo SQL Server, Redis Cache\n- Có tư duy thiết kế hệ thống Microservices sạch sẽ.', N'- Mức lương cạnh tranh từ 30 - 45 triệu\n- Thưởng dự án và tháng lương 13\n- Bảo hiểm sức khỏe PVI cao cấp\n- Môi trường làm việc trẻ trung, trang thiết bị Macbook Pro.', N'30,000,000 - 45,000,000 VND', N'Tầng 8, Tòa nhà RMS Tower, Phố Duy Tân, Cầu Giấy, Hà Nội', '2026-09-25 08:00:00', '2026-12-31 23:59:59', N'Published', 3, '2026-09-25 08:00:00');
INSERT INTO JobPosting (RequisitionId, PostingTitle, JobDescription, JobRequirements, Benefits, SalaryDisplay, WorkLocation, PostingDate, ApplicationDeadline, PostingStatus, CreatedBy, CreatedAt) VALUES (2, N'Frontend ReactJS Developer (TypeScript / Next.js)', N'Gia nhập đội ngũ Frontend để phát triển cổng thông tin quản trị và trải nghiệm ứng viên mượt mà, chuẩn UI/UX.', N'- Tối thiểu 2 năm kinh nghiệm ReactJS, TypeScript\n- Khả năng xây dựng Responsive Web và Design System hiện đại\n- Thành thạo Redux Toolkit hoặc Zustand.', N'- Thu nhập 20 - 32 triệu\n- Review lương 2 lần/năm\n- Du lịch công ty hằng năm\n- Hỗ trợ chi phí chứng chỉ chuyên môn quốc tế.', N'20,000,000 - 32,000,000 VND', N'Tầng 8, Tòa nhà RMS Tower, Phố Duy Tân, Cầu Giấy, Hà Nội', '2026-09-25 08:30:00', '2026-12-31 23:59:59', N'Published', 3, '2026-09-25 08:30:00');
INSERT INTO JobPosting (RequisitionId, PostingTitle, JobDescription, JobRequirements, Benefits, SalaryDisplay, WorkLocation, PostingDate, ApplicationDeadline, PostingStatus, CreatedBy, CreatedAt) VALUES (3, N'QA Automation Engineer (Playwright / Selenium / API)', N'Đảm bảo chất lượng các bản phát hành phần mềm bằng hệ thống kiểm thử tự động toàn diện và liên tục.', N'- Tối thiểu 2 năm kinh nghiệm Automation Test web và API\n- Nắm vững Playwright hoặc Selenium\n- Kinh nghiệm CI/CD với GitLab/GitHub Actions.', N'- Thu nhập 18 - 28 triệu\n- Phụ cấp ăn trưa, gửi xe\n- Tham gia các khóa đào tạo nâng cao kỹ năng kiểm thử và bảo mật.', N'18,000,000 - 28,000,000 VND', N'Tầng 8, Tòa nhà RMS Tower, Phố Duy Tân, Cầu Giấy, Hà Nội', '2026-09-25 09:00:00', '2026-12-31 23:59:59', N'Published', 3, '2026-09-25 09:00:00');
INSERT INTO JobPosting (RequisitionId, PostingTitle, JobDescription, JobRequirements, Benefits, SalaryDisplay, WorkLocation, PostingDate, ApplicationDeadline, PostingStatus, CreatedBy, CreatedAt) VALUES (4, N'Chuyên Viên Phát Triển Kinh Doanh B2B (Software Solutions)', N'Tìm kiếm và phát triển mạng lưới khách hàng doanh nghiệp sử dụng hệ thống phần mềm quản trị RMS.', N'- Tối thiểu 1 năm kinh nghiệm kinh doanh B2B ngành CNTT / SaaS\n- Khả năng giao tiếp, thương lượng và chốt deal xuất sắc\n- Tinh thần chủ động, trách nhiệm cao.', N'- Lương cứng 15 - 25 triệu + Hoa hồng doanh số hấp dẫn\n- Thu nhập trung bình 30 - 45 triệu/tháng\n- Lộ trình thăng tiến rõ ràng lên Trưởng nhóm kinh doanh.', N'15,000,000 - 25,000,000 VND + Hoa hồng', N'Quận 1, TP. Hồ Chí Minh & Cầu Giấy, Hà Nội', '2026-09-25 09:30:00', '2026-12-31 23:59:59', N'Published', 3, '2026-09-25 09:30:00');
